"""Hippie Station Medbay, generated by the node graph (forge/proc), the second department through it.

    python tools/mapforge/blueprints/medbay_v2.py            # run the graph, one picture per node
    python tools/mapforge/mapforge.py build blueprints/medbay_v2.py

Medbay's footprint is not one block: a lobby on the main hall, a corridor band, a ward band around the cryo bay
(kept: its tubes need their coolant loop), a surgical band, an east wing and the morgue. Each block is its own
slicing plan; tiles between plans become the walls between them. The program is the user's (2026-11-14):
MetaStation's medbay with one operating theatre and a real store room.
"""
import os
import random
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(HERE, ".."))
from forge.proc import geo as G  # noqa: E402
from forge.proc import shell, furnish, emit, solve  # noqa: E402
from assets import medical as assets  # noqa: E402
from forge.proc.shell import X, Y, door, desk, glass, keep  # noqa: E402

NAME = "medbay_v2"
ROOT = os.path.abspath(os.path.join(HERE, "..", "..", ".."))
BASE_MAP = os.path.join(ROOT, "_maps", "map_files", "HippieStation", "hippiestation.dmm")
BBOX = (130, 102, 162, 128)
AREAS = ("/area/medical/sleeper", "/area/medical/medbay/central", "/area/crew_quarters/heads/cmo", "/area/medical/morgue")

# ---------------------------------------------------------------- inputs: what the outline fixes
ENTRANCE = [(142, 127), (143, 127)]          # the open public way in from the main hall
CHEM_DOOR = (135, 117)                       # chemistry's door onto the corridor, and the window beside it
CHEM_WINDOW = (135, 118)
MORGUE_HALL_DOOR = (153, 127)                # bodies leave by the main hall
CRYO = [(x, y) for x in range(143, 148) for y in range(112, 116)]   # the cryo bay, kept whole


def in_zone(a):
    return a in AREAS


PARAMS = dict(reception=2, recovery=5, theatre=5, scrub=3, patient=3, seed=1)

MED = "/area/medical"
WHITE = "/turf/open/floor/plasteel/white"
ROOM_TABLE = {
    "lobby": dict(area=MED + "/medbay/lobby", floor=WHITE, name="Medbay Lobby", newscaster=True, label="LOBBY"),
    "reception": dict(area=MED + "/medbay/lobby", floor=WHITE, name="Medbay Reception", main=False, label="DESK"),
    "medhall": dict(area=MED + "/medbay/central", floor=WHITE, name="Medbay", hall=True, label="MEDBAY"),
    "recovery": dict(area=MED + "/sleeper", floor=WHITE, name="Recovery Room", label="WARD"),
    "scrub": dict(area=MED + "/medbay/aft", floor=WHITE, name="Surgical Scrub", label="SCRUB"),
    "theatre": dict(area=MED + "/surgery", floor=WHITE, name="Operating Theatre", label="THEATRE"),
    "medstore": dict(area=MED + "/storage", floor=WHITE, name="Medbay Storage", label="STORE"),
    "roomA": dict(area=MED + "/patients_rooms/room_a", floor=WHITE, name="Patient Room A", camera=False, label="A"),
    "roomB": dict(area=MED + "/patients_rooms/room_b", floor=WHITE, name="Patient Room B", camera=False, label="B"),
    "cmo": dict(area="/area/crew_quarters/heads/cmo", floor="/turf/open/floor/plasteel/cafeteria",
                name="Chief Medical Officer's Office", label="CMO"),
    "morgue": dict(area=MED + "/morgue", floor="/turf/open/floor/plasteel/dark", name="Morgue", label="MORGUE"),
}


CX0, CX1 = min(p[0] for p in CRYO), max(p[0] for p in CRYO)
CY0, CY1 = min(p[1] for p in CRYO), max(p[1] for p in CRYO)
SOUTH = (132, 106, 147, CY0 - 2)        # the surgical band under the ward
EAST = (149, 103, 160, CY0 - 1)         # the east wing: its hall opens straight onto the ward's way through


def authored(P):
    """The plan as I drew it for the two free blocks."""
    rooms = Y((2, "roomA"), (1.0, "roomB"))
    return {
        "S": X((P["theatre"], "theatre"), (P["scrub"], "scrub"), (1.0, "medstore")),
        "E": X((7, Y((3, "medhall"), (1.0, X((P["patient"], rooms), (1.0, "medhall"))))), (1.0, "cmo")),
    }


def plans(P, fill=None):
    ward_x0 = CX0 - P["recovery"]
    f = fill or authored(P)
    lobby = X((P["reception"], "reception"), (1.0, "lobby"))
    # the ward is one open floor with the cryo bay: recovery west of it, the way through east of it, no walls between
    ward = X((P["recovery"], "recovery"), (CX1 - CX0 + 1, "-"), (1.0, "medhall"), wall=0)
    return [
        ((ward_x0, 122, 144, 126), lobby),
        ((136, CY1 + 2, 150, 120), "medhall"),                  # the corridor band above the ward
        ((ward_x0, CY0, 150, CY1), ward),
        (SOUTH, f["S"]),
        (EAST, f["E"]),
        ((150, 122, 156, 126), "morgue"),
    ]


def program(P):
    """The two free blocks as a room list. Fixed around them: the lobby, the corridor, the ward with the cryo bay, the
    morgue. The surgical band's north wall is the recovery ward's (the scrub room's way in); its east end looks onto
    the east wing's hall, which must run from the ward's way through (the tiles it is anchored to)."""
    ward_x0 = CX0 - P["recovery"]
    blocks = [
        solve.Block("S", SOUTH, {"n": ("ward", ward_x0, CX0 - 1), "e": ("hall", SOUTH[3] - 1, SOUTH[3])}),
        solve.Block("E", EAST, {"n": ("ward", EAST[0], EAST[0] + 1)}),
    ]
    W = solve.Want
    hx, hy = EAST[0], EAST[3]
    wants = [
        W("theatre", 25 + 5 * (P["theatre"] - 5), min=(4, 5), front=()),
        W("scrub", 15 + 5 * (P["scrub"] - 3), min=(3, 4), front=("ward",)),
        W("medstore", 28, min=(3, 5), front=("hall",), near=("scrub",)),
        W("cmo", 24, min=(4, 5), front=("hall",)),
        W("roomA", 6 + 2 * (P["patient"] - 3), min=(2, 3), front=("hall",)),
        W("roomB", 6 + 2 * (P["patient"] - 3), min=(2, 3), front=("hall",)),
        # the east hall: anchored where it meets the ward and where the surgical band looks onto it
        W("hall_e", 24, min=(3, 3), corridor=True, front=(), anchors=[(hx, hy), (hx + 1, hy), (hx, SOUTH[3] - 1)],
          provides=("hall",), node="medhall"),
    ]
    return blocks, wants


LINK_PAIRS = [("theatre", "scrub")]


def seeded(seed, tries=8):
    """A seed's plan: the solver arranges the two free blocks, the graph judges it; first clean try wins."""
    last = None
    for t in range(tries):
        P = dict(PARAMS)
        blocks, wants = program(P)
        trees, rects, report = solve.solve(blocks, wants, LINK_PAIRS, seed="%s.%d" % (seed, t), ratio=(0.4, 1.5), fill=True)
        if trees is None:
            break
        g = graph(fill=trees)
        geo = g.run()
        geo.notes[:0] = report + ["seed %s: try %d, %d problems" % (seed, t, len(geo.problems))]
        last = (g, geo)
        if not geo.problems:
            break
    return last


LINKS = [
    keep(ENTRANCE[0], "lobby"), keep(ENTRANCE[1], "lobby"), keep(CHEM_DOOR, "medhall"), keep(MORGUE_HALL_DOOR, "morgue"),
    # the public front: a desk nobody can walk behind, glass doors into the ward corridor
    desk("reception", "lobby", name="Medbay Reception", access="5", id="med_reception"),
    door("reception", "medhall", name="Medbay Reception", access="5", kind="medical"),
    door("lobby", "medhall", wide=2, name="Medbay", access="5", kind="medical", glass=True),
    glass("lobby", "medhall", runs="door"),
    # the ward
    door("recovery", "medhall", name="Recovery Room", access="5", kind="medical", glass=True),
    glass("recovery", "medhall"),
    glass("medhall", "keep", inset=1),                      # the corridor looks into the cryo bay, between two pillars
    # the surgical wing: ward -> scrub -> theatre, the store off the scrub room and off the east hall
    door("scrub", "recovery", name="Surgical Wing", access="5", kind="medical", glass=True),
    glass("scrub", "recovery"),
    door("theatre", "scrub", name="Operating Theatre", access="45", kind="medical"),
    glass("theatre", "scrub", inset=1),
    door("medstore", "scrub", name="Medbay Storage", access="5", kind="medical"),
    door("medstore", "medhall", name="Medbay Storage", access="5", kind="medical", glass=True),
    # the east wing
    door("roomA", "medhall", name="Patient Room A", access="5", kind="medical"),
    door("roomB", "medhall", name="Patient Room B", access="5", kind="medical"),
    door("cmo", "medhall", name="Chief Medical Officer", access="40", kind="command", glass=True),
    door("morgue", "medhall", name="Morgue", access="6", kind="medical"),
]


ROLL = dict(reception=(2, 3), recovery=(5, 6), theatre=(5, 6), scrub=(3, 4), patient=(3, 4))


def rolled(seed):
    """Seed 1 is the authored layout. Any other seed picks each size from its range and nudges every placement."""
    if seed == 1:
        return {}
    rng = random.Random(seed)
    out = {k: rng.randint(lo, hi) for k, (lo, hi) in sorted(ROLL.items())}
    out["seed"] = seed
    return out


SEED = int(os.environ.get("MAPFORGE_SEED", "1"))
if SEED != 1:
    PARAMS.update(rolled(SEED))
    NAME += "_s%d" % SEED


def graph(fill=None, **over):
    P = dict(PARAMS)
    P.update(over)
    g = G.Graph(NAME, **P)
    g.add("outline", shell.outline, view="kind", base=BASE_MAP, bbox=BBOX, in_zone=in_zone,
          keep=[CHEM_WINDOW], gates=ENTRANCE + [CHEM_DOOR, MORGUE_HALL_DOOR], inside=CRYO)
    g.add("slice", shell.slice_rooms, view="rooms", plans=plans(P, fill), rooms=ROOM_TABLE)
    g.add("tidy", shell.tidy, view="rooms")
    g.add("openings", shell.openings, view="rooms", links=LINKS)
    g.add("fields", shell.fields, view="fields")
    g.add("furnish", furnish.furnish, view="items", assets=assets.ASSETS)
    return g


_graph, _geo = seeded(SEED) if SEED != 1 else (graph(), None)
_geo = _geo or _graph.run()
globals().update(emit.blueprint(_geo, NAME, extra=dict(STYLE="meta", DISPOSALS="route", DRESS_HALL_FRONT=True,
                                                       BASE=BASE_MAP)))


def main():
    g, geo = _graph, _geo
    out = os.path.join(ROOT, "data", "previews", "mapforge", "proc")
    paths = g.pictures(out, tile=20)
    G.sheet(paths, os.path.join(out, NAME + "_nodes.png"), cols=3)
    G.draw(geo, "items", os.path.join(out, NAME + "_furnish_big.png"), tile=30, title="furnish")
    for n in geo.notes:
        print(n)
    for p in geo.problems:
        print("PROBLEM", p)
    print("pictures:", os.path.relpath(os.path.join(out, NAME + "_nodes.png"), ROOT))


WEDGE = [
    ("as built", {}),
    ("wider theatre, narrower store", dict(theatre=6)),
    ("wider scrub room", dict(scrub=4)),
    ("wider patient rooms, narrower east hall", dict(patient=4)),
]


def wedge():
    """The same graph under different parameters, side by side."""
    out = os.path.join(ROOT, "data", "previews", "mapforge", "proc")
    paths = []
    for i, (label, over) in enumerate(WEDGE):
        geo = graph(**over).run()
        path = os.path.join(out, "%s_wedge_%d.png" % (NAME, i))
        G.draw(geo, "items", path, tile=18, title="%s  (%d problems)" % (label, len(geo.problems)))
        paths.append(path)
        print("%-44s %d problems" % (label, len(geo.problems)))
        for p in geo.problems:
            print("   ", p)
    print("pictures:", os.path.relpath(G.sheet(paths, os.path.join(out, NAME + "_wedge.png"), cols=2), ROOT))


if __name__ == "__main__":
    wedge() if "--wedge" in sys.argv else main()
